186	// Load loads the Entire settings from .entire/settings.json,
187	// then applies any overrides from .entire/settings.local.json if it exists.
188	// Returns default settings if neither file exists.
189	// Works correctly from any subdirectory within the repository.
190	func Load(ctx context.Context) (*EntireSettings, error) {
191		// Get absolute paths for settings files
192		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
193		if err != nil {
194			settingsFileAbs = EntireSettingsFile // Fallback to relative
195		}
