256	func loadFromFile(filePath string) (*EntireSettings, error) {
257		settings := &EntireSettings{
258			Enabled: true, // Default to enabled
259		}
260	
261		data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
262		if err != nil {
263			if os.IsNotExist(err) {
264				return settings, nil
265			}
266			return nil, fmt.Errorf("%w", err)
267		}
268	
269		dec := json.NewDecoder(bytes.NewReader(data))
270		dec.DisallowUnknownFields()
271		if err := dec.Decode(settings); err != nil {
272			return nil, fmt.Errorf("parsing settings file: %w", err)
273		}
274	
275		// Validate commit_linking if set
276		if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
277			return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
278		}
279	
280		// SummaryGeneration is NOT validated here — individual files may
281		// legitimately contain only a model (provider comes from another file).
282		// Validation happens after merge in Load().
283	
284		return settings, nil
285	}
286	
287	// mergeJSON merges JSON data into existing settings.
288	// Only non-zero values from the JSON override existing settings.
289	func mergeJSON(settings *EntireSettings, data []byte) error {
290		// Validate that there are no unknown keys using strict decoding.
291		dec := json.NewDecoder(bytes.NewReader(data))
292		dec.DisallowUnknownFields()
293		var temp EntireSettings
294		if err := dec.Decode(&temp); err != nil {
295			return fmt.Errorf("parsing JSON: %w", err)
296		}
297	
298		// Parse into a map to check which fields are present.
299		var raw map[string]json.RawMessage
300		if err := json.Unmarshal(data, &raw); err != nil {
301			return fmt.Errorf("parsing JSON: %w", err)
302		}
303	
304		if err := mergeScalarFields(settings, raw); err != nil {
305			return err
306		}
307		if err := mergeStrategyOptions(settings, raw); err != nil {
308			return err
309		}
310		if err := mergeSummaryGeneration(settings, raw); err != nil {
311			return err
312		}
313		if err := mergeCommitLinking(settings, raw); err != nil {
314			return err
315		}
316	
317		// Merge redaction sub-fields if present (field-level, not wholesale replace).
318		if redactionRaw, ok := raw["redaction"]; ok {
319			if settings.Redaction == nil {
320				settings.Redaction = &RedactionSettings{}
321			}
322			if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
323				return fmt.Errorf("parsing redaction field: %w", err)
324			}
325		}
326	
327		return nil
328	}
329	
330	// mergeScalarFields merges simple bool, *bool, string, and int fields from raw JSON.
331	func mergeScalarFields(settings *EntireSettings, raw map[string]json.RawMessage) error {
332		if err := mergeRawBool(raw, "enabled", &settings.Enabled); err != nil {
333			return err
334		}
335		if err := mergeRawBool(raw, "local_dev", &settings.LocalDev); err != nil {
336			return err
337		}
338		if err := mergeRawBool(raw, "absolute_git_hook_path", &settings.AbsoluteGitHookPath); err != nil {
339			return err
340		}
341		if err := mergeRawBool(raw, "external_agents", &settings.ExternalAgents); err != nil {
342			return err
343		}
344		if err := mergeRawBool(raw, "vercel", &settings.Vercel); err != nil {
345			return err
346		}
347		if err := mergeRawBoolPtr(raw, "telemetry", &settings.Telemetry); err != nil {
348			return err
349		}
350		if err := mergeRawBoolPtr(raw, "sign_checkpoint_commits", &settings.SignCheckpointCommits); err != nil {
351			return err
352		}
353		if err := mergeRawStringNonEmpty(raw, "log_level", &settings.LogLevel); err != nil {
354			return err
355		}
356		if err := mergeRawInt(raw, "summary_timeout_seconds", &settings.SummaryTimeoutSeconds); err != nil {
357			return err
358		}
359		return nil
360	}
361	
362	func mergeRawBool(raw map[string]json.RawMessage, key string, dst *bool) error {
363		v, ok := raw[key]
364		if !ok {
365			return nil
366		}
367		return unmarshalField(key, v, dst)
368	}
369	
370	func mergeRawBoolPtr(raw map[string]json.RawMessage, key string, dst **bool) error {
371		v, ok := raw[key]
372		if !ok {
373			return nil
374		}
375		var b bool
376		if err := unmarshalField(key, v, &b); err != nil {
377			return err
378		}
379		*dst = &b
380		return nil
381	}
382	
383	func mergeRawStringNonEmpty(raw map[string]json.RawMessage, key string, dst *string) error {
384		v, ok := raw[key]
385		if !ok {
386			return nil
387		}
388		var s string
389		if err := unmarshalField(key, v, &s); err != nil {
390			return err
391		}
392		if s != "" {
393			*dst = s
394		}
395		return nil
396	}
397	
398	func mergeRawInt(raw map[string]json.RawMessage, key string, dst *int) error {
399		v, ok := raw[key]
400		if !ok {
401			return nil
402		}
403		return unmarshalField(key, v, dst)
404	}
405	
406	func unmarshalField(key string, data json.RawMessage, dst any) error {
407		if err := json.Unmarshal(data, dst); err != nil {
408			return fmt.Errorf("parsing %s field: %w", key, err)
409		}
410		return nil
411	}
412	
413	func mergeStrategyOptions(settings *EntireSettings, raw map[string]json.RawMessage) error {
414		optionsRaw, ok := raw["strategy_options"]
415		if !ok {
416			return nil
417		}
418		var opts map[string]any
419		if err := unmarshalField("strategy_options", optionsRaw, &opts); err != nil {
420			return err
421		}
422		if settings.StrategyOptions == nil {
423			settings.StrategyOptions = opts
424		} else {
425			for k, v := range opts {
426				settings.StrategyOptions[k] = v
427			}
428		}
429		return nil
430	}
431	
432	func mergeSummaryGeneration(settings *EntireSettings, raw map[string]json.RawMessage) error {
433		summaryRaw, ok := raw["summary_generation"]
434		if !ok {
435			return nil
436		}
437		if settings.SummaryGeneration == nil {
438			settings.SummaryGeneration = &SummaryGenerationSettings{}
439		}
440	
441		var summaryFields map[string]json.RawMessage
442		if err := unmarshalField("summary_generation", summaryRaw, &summaryFields); err != nil {
443			return err
444		}
445	
446		_, modelInOverride := summaryFields["model"]
447	
448		if providerRaw, ok := summaryFields["provider"]; ok {
449			var provider string
450			if err := unmarshalField("summary_generation.provider", providerRaw, &provider); err != nil {
451				return err
452			}
453			// If the override switches providers without also setting a model,
454			// the base's model was tuned to the old provider and would likely
455			// cause a runtime failure when handed to the new one (e.g. codex
456			// rejecting "sonnet"). Clear it so the new provider falls back to
457			// its own default.
458			if provider != settings.SummaryGeneration.Provider && !modelInOverride {
459				settings.SummaryGeneration.Model = ""
460			}
461			settings.SummaryGeneration.Provider = provider
462		}
463	
464		if modelRaw, ok := summaryFields["model"]; ok {
465			var model string
466			if err := unmarshalField("summary_generation.model", modelRaw, &model); err != nil {
467				return err
468			}
469			settings.SummaryGeneration.Model = model
470		}
471		return nil
472	}
473	
474	func mergeCommitLinking(settings *EntireSettings, raw map[string]json.RawMessage) error {
475		commitLinkingRaw, ok := raw["commit_linking"]
476		if !ok {
477			return nil
478		}
479		var cl string
480		if err := unmarshalField("commit_linking", commitLinkingRaw, &cl); err != nil {
481			return err
482		}
483		if cl == "" {
484			return nil
485		}
486		switch cl {
487		case CommitLinkingAlways, CommitLinkingPrompt:
488			settings.CommitLinking = cl
489		default:
490			return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
491		}
492		return nil
493	}
494	
495	// mergeRedaction merges redaction overrides into existing RedactionSettings.
496	// Only fields present in the override JSON are applied.
497	func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
498		var raw map[string]json.RawMessage
499		if err := json.Unmarshal(data, &raw); err != nil {
500			return fmt.Errorf("parsing redaction: %w", err)
501		}
502		if piiRaw, ok := raw["pii"]; ok {
503			if dst.PII == nil {
504				dst.PII = &PIISettings{}
505			}
506			if err := mergePIISettings(dst.PII, piiRaw); err != nil {
507				return err
508			}
509		}
510		return nil
511	}
512	
513	// mergePIISettings merges PII overrides into existing PIISettings.
514	// Only fields present in the override JSON are applied; missing fields
515	// are preserved from the base settings.
516	func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
517		var raw map[string]json.RawMessage
518		if err := json.Unmarshal(data, &raw); err != nil {
519			return fmt.Errorf("parsing pii: %w", err)
520		}
521		if v, ok := raw["enabled"]; ok {
522			if err := json.Unmarshal(v, &dst.Enabled); err != nil {
523				return fmt.Errorf("parsing pii.enabled: %w", err)
524			}
525		}
526		if v, ok := raw["email"]; ok {
527			var b bool
528			if err := json.Unmarshal(v, &b); err != nil {
529				return fmt.Errorf("parsing pii.email: %w", err)
530			}
531			dst.Email = &b
532		}
533		if v, ok := raw["phone"]; ok {
534			var b bool
535			if err := json.Unmarshal(v, &b); err != nil {
536				return fmt.Errorf("parsing pii.phone: %w", err)
537			}
538			dst.Phone = &b
539		}
540		if v, ok := raw["address"]; ok {
541			var b bool
542			if err := json.Unmarshal(v, &b); err != nil {
543				return fmt.Errorf("parsing pii.address: %w", err)
544			}
545			dst.Address = &b
546		}
547		if v, ok := raw["custom_patterns"]; ok {
548			var cp map[string]string
549			if err := json.Unmarshal(v, &cp); err != nil {
550				return fmt.Errorf("parsing pii.custom_patterns: %w", err)
551			}
552			if dst.CustomPatterns == nil {
553				dst.CustomPatterns = cp
554			} else {
555				for k, val := range cp {
556					dst.CustomPatterns[k] = val
557				}
558			}
559		}
560		return nil
561	}
