563	// IsSetUp returns true if Entire has been set up in the current repository.
564	// This checks if .entire/settings.json exists.
565	// Use this to avoid creating files/directories in repos where Entire was never enabled.
566	func IsSetUp(ctx context.Context) bool {
567		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
568		if err != nil {
569			return false
570		}
571		_, err = os.Stat(settingsFileAbs)
572		return err == nil
573	}
