575	// IsSetUpAny returns true if Entire has been set up in the current repository,
576	// checking both .entire/settings.json and .entire/settings.local.json.
577	// Use this to detect any prior setup, even if only local settings exist.
578	func IsSetUpAny(ctx context.Context) bool {
579		if IsSetUp(ctx) {
580			return true
581		}
582		localFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
583		if err != nil {
584			return false
585		}
586		_, err = os.Lstat(localFileAbs)
