669	// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
670	func (s *EntireSettings) IsSummarizeEnabled() bool {
671		if s.StrategyOptions == nil {
672			return false
673		}
674		summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
675		if !ok {
676			return false
677		}
678		enabled, ok := summarizeOpts["enabled"].(bool)
679		if !ok {
