685	// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
686	// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
687	type CheckpointRemoteConfig struct {
688		Provider string // e.g., "github"
689		Repo     string // e.g., "org/checkpoints-repo"
690	}
691	
692	// Owner returns the owner portion of the repo field (before the slash).
693	// Returns empty string if the repo field doesn't contain a slash.
694	func (c *CheckpointRemoteConfig) Owner() string {
695		parts := strings.SplitN(c.Repo, "/", 2)
696		if len(parts) < 2 {
697			return ""
698		}
699		return parts[0]
700	}
701	
702	// GetCheckpointRemote returns the configured checkpoint remote.
703	// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
704	// Returns nil if not configured, wrong type, or missing required fields.
705	func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
706		if s.StrategyOptions == nil {
707			return nil
708		}
709		val, ok := s.StrategyOptions["checkpoint_remote"]
710		if !ok {
711			return nil
712		}
713		m, ok := val.(map[string]any)
714		if !ok {
715			return nil
716		}
717		provider, providerOK := m["provider"].(string)
718		repo, repoOK := m["repo"].(string)
719		if !providerOK || !repoOK || provider == "" || repo == "" {
720			return nil
721		}
722		if !strings.Contains(repo, "/") {
723			return nil
724		}
725		return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
726	}
727	
728	// IsCheckpointsV2Enabled checks if checkpoints v2 is enabled.
729	// Returns true when either checkpoints_v2 is set or checkpoints_version is 2.
730	func (s *EntireSettings) IsCheckpointsV2Enabled() bool {
731		if s.CheckpointsVersion() == 2 {
732			return true
733		}
734		if s.StrategyOptions == nil {
735			return false
736		}
737		val, ok := s.StrategyOptions["checkpoints_v2"].(bool)
738		return ok && val
739	}
740	
741	// CheckpointsVersion returns the configured checkpoints format version from
742	// strategy_options.checkpoints_version. Returns 1 when unset, invalid, or
743	// unsupported. The currently supported versions are 1 and 2.
744	func (s *EntireSettings) CheckpointsVersion() int {
745		if s.StrategyOptions == nil {
746			return 1
747		}
748		val, ok := s.StrategyOptions["checkpoints_version"]
749		if !ok {
750			return 1
751		}
752		version, ok := parseCheckpointsVersion(val)
753		if ok {
754			return version
755		}
756		return 1
757	}
758	
759	func parseCheckpointsVersion(val any) (int, bool) {
760		v, ok := val.(int)
761		if ok && (v == 1 || v == 2) {
762			return v, true
763		}
764		floatV, ok := val.(float64)
765		if ok && (floatV == 1 || floatV == 2) {
766			return int(floatV), true
767		}
768		stringV, ok := val.(string)
769		if ok {
770			parsed, err := strconv.Atoi(stringV)
771			if err == nil && (parsed == 1 || parsed == 2) {
772				return parsed, true
773			}
774		}
775		return 1, false
776	}
777	
778	// IsPushV2RefsEnabled checks if pushing v2 refs is enabled.
779	// checkpoints_version: 2 forces v2 ref pushes on, regardless of push_v2_refs.
780	func (s *EntireSettings) IsPushV2RefsEnabled() bool {
781		if s.CheckpointsVersion() == 2 {
782			return true
783		}
784		if !s.IsCheckpointsV2Enabled() {
785			return false
786		}
787		if s.StrategyOptions == nil {
788			return false
789		}
790		val, ok := s.StrategyOptions["push_v2_refs"].(bool)
791		return ok && val
792	}
793	
794	// GetFullTranscriptGenerationRetentionDays returns the retention window for
795	// archived checkpoints v2 /full/* generations. Invalid, missing, or
796	// non-positive values fall back to the documented default.
797	func (s *EntireSettings) GetFullTranscriptGenerationRetentionDays() int {
798		if s.StrategyOptions == nil {
799			return defaultGenerationRetentionDays
800		}
801	
802		val, ok := s.StrategyOptions["full_transcript_generation_retention_days"]
803		if !ok {
804			return defaultGenerationRetentionDays
805		}
806	
807		switch days := val.(type) {
808		case int:
809			if days > 0 {
810				return days
811			}
812		case float64:
813			intDays := int(days)
814			if intDays > 0 && days == float64(intDays) {
815				return intDays
816			}
817		}
818	
819		return defaultGenerationRetentionDays
820	}
821	
822	// IsFilteredFetchesEnabled checks if fetches should use --filter=blob:none.
823	// When enabled, filtered fetches always use resolved URLs rather than remote
824	// names to avoid persisting promisor settings onto named remotes.
825	func (s *EntireSettings) IsFilteredFetchesEnabled() bool {
826		if s.StrategyOptions == nil {
827			return false
828		}
829		val, ok := s.StrategyOptions["filtered_fetches"].(bool)
830		return ok && val
831	}
832	
833	// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
834	// Returns true if push_sessions is explicitly set to false.
835	func (s *EntireSettings) IsPushSessionsDisabled() bool {
836		if s.StrategyOptions == nil {
837			return false
838		}
839		val, exists := s.StrategyOptions["push_sessions"]
840		if !exists {
841			return false
842		}
843		if boolVal, ok := val.(bool); ok {
844			return !boolVal // disabled = !push_sessions
845		}
846		return false
847	}
848	
849	// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
850	// Returns false by default if settings cannot be loaded or the key is missing.
851	func IsExternalAgentsEnabled(ctx context.Context) bool {
852		s, err := Load(ctx)
853		if err != nil {
854			return false
855		}
856		return s.ExternalAgents
857	}
858	
859	// IsSignCheckpointCommitsEnabled returns true if checkpoint commits should be signed.
860	// Defaults to true when the setting is not explicitly set.
861	func (s *EntireSettings) IsSignCheckpointCommitsEnabled() bool {
862		return s.SignCheckpointCommits == nil || *s.SignCheckpointCommits
863	}
864	
865	// IsSignCheckpointCommitsEnabled checks if checkpoint commit signing is enabled in settings.
866	// Returns true by default if settings cannot be loaded or the key is missing.
867	func IsSignCheckpointCommitsEnabled(ctx context.Context) bool {
868		s, err := Load(ctx)
869		if err != nil {
870			return true
871		}
872		return s.IsSignCheckpointCommitsEnabled()
873	}
874	
875	// Save saves the settings to .entire/settings.json.
876	func Save(ctx context.Context, settings *EntireSettings) error {
877		return saveToFile(ctx, settings, EntireSettingsFile)
878	}
879	
880	// SaveLocal saves the settings to .entire/settings.local.json.
881	func SaveLocal(ctx context.Context, settings *EntireSettings) error {
882		return saveToFile(ctx, settings, EntireSettingsLocalFile)
883	}
884	
885	// saveToFile saves settings to the specified file path.
886	func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
887		// Get absolute path for the file
888		filePathAbs, err := paths.AbsPath(ctx, filePath)
889		if err != nil {
890			filePathAbs = filePath // Fallback to relative
891		}
892	
893		// Ensure directory exists
894		dir := filepath.Dir(filePathAbs)
895		if err := os.MkdirAll(dir, 0o750); err != nil {
896			return fmt.Errorf("creating settings directory: %w", err)
897		}
898	
899		data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
900		if err != nil {
901			return fmt.Errorf("marshaling settings: %w", err)
902		}
903	
904		//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
905		if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
906			return fmt.Errorf("writing settings file: %w", err)
907		}
908		return nil
909	}
